import csv
import io
from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class StudentRecord:
    student_id: str
    name: str
    score: int

    def __post_init__(self) -> None:
        object.__setattr__(self, "student_id", self.student_id.strip())
        object.__setattr__(self, "name", self.name.strip())
        if not self.student_id or not self.name:
            raise ValueError("student_id and name cannot be blank")
        if isinstance(self.score, bool) or not isinstance(self.score, int) or not 0 <= self.score <= 100:
            raise ValueError("score must be an integer from 0 to 100")


class Formatter(Protocol):
    def format(self, records: list[StudentRecord]) -> str: ...


class TextFormatter:
    def format(self, records: list[StudentRecord]) -> str:
        if not records:
            return "(empty)"
        return "\n".join(f"{r.student_id} | {r.name} | {r.score}" for r in records)


class CsvFormatter:
    def format(self, records: list[StudentRecord]) -> str:
        stream = io.StringIO(newline="")
        writer = csv.writer(stream, lineterminator="\n")
        writer.writerow(["student_id", "name", "score"])
        writer.writerows([r.student_id, r.name, r.score] for r in records)
        return stream.getvalue()


class GradeBook:
    def __init__(self) -> None:
        self._records: dict[str, StudentRecord] = {}

    def add(self, record: StudentRecord) -> bool:
        if record.student_id in self._records:
            return False
        self._records[record.student_id] = record
        return True

    def export(self, formatter: Formatter) -> str:
        ordered = sorted(self._records.values(), key=lambda r: r.student_id)
        result = formatter.format(ordered)
        if not isinstance(result, str):
            raise TypeError("formatter must return str")
        return result


class BadFormatter:
    def format(self, records: list[StudentRecord]) -> int:
        return len(records)


def expect(error_type: type[Exception], action) -> None:
    try:
        action()
    except error_type:
        return
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    empty = GradeBook()
    assert empty.export(TextFormatter()) == "(empty)"
    assert empty.export(CsvFormatter()) == "student_id,name,score\n"

    book = GradeBook()
    assert book.add(StudentRecord("S02", "林安", 0))
    assert book.add(StudentRecord("S01", "Amy, A.", 95))
    assert not book.add(StudentRecord("S01", "Other", 60))
    assert book.export(TextFormatter()) == "S01 | Amy, A. | 95\nS02 | 林安 | 0"
    assert book.export(CsvFormatter()) == 'student_id,name,score\nS01,"Amy, A.",95\nS02,林安,0\n'

    expect(ValueError, lambda: StudentRecord("S03", " ", 70))
    expect(ValueError, lambda: StudentRecord("S03", "Bo", True))
    expect(ValueError, lambda: StudentRecord("S03", "Bo", 101))
    expect(TypeError, lambda: book.export(BadFormatter()))


if __name__ == "__main__":
    run_checks()
    print("weekend-report checks: OK")
